{# Web Template: Company Cards (with Add Company button) #}
{% if frappe.session.user == "Guest" %}
  <div class="alert alert-danger">
    You must be logged in to view this page. <a href="/login">Login</a>
  </div>
{% else %}

  <div class="d-flex justify-content-between align-items-center mb-3">
    <h2 class="mb-0">Companies</h2>
    <a class="btn btn-primary" href="/new-company/new">Create Company</a>
  </div>

  {% set companies = frappe.get_all(
    "Company",
    fields=["name","company_name","phone","email","website","address"]
  ) %}

  {% if not companies %}
    <div class="alert alert-info">No companies yet. Click <strong>Create Company</strong> to add one.</div>
  {% else %}
    <div class="row">
      {% for c in companies %}
        {# Normalize website to absolute URL if present #}
        {% if c.website %}
          {% set _site = c.website.strip() %}
          {% set external_website = _site if '://' in _site else ('https://' ~ _site) %}
        {% endif %}

        <div class="col-md-4">
          <div class="card mb-3">
            <div class="card-body">
              <h5 class="card-title mb-1">
                <a href="/company-dashboard?company={{ c.name | urlencode }}">{{ c.company_name or c.name }}</a>
              </h5>
              <div class="text-muted small mb-2"><strong>Code:</strong> {{ c.name }}</div>

              {% if c.phone or c.email %}
                <div class="small text-muted">
                  {{ c.phone or '' }}{% if c.phone and c.email %} • {% endif %}{{ c.email or '' }}
                </div>
              {% endif %}

              {% if c.address %}
                <p class="card-text mt-2 mb-3">{{ c.address }}</p>
              {% endif %}

              <div class="d-flex gap-2">
                {# Removed "Open Record" button intentionally #}
                {% if c.website %}
                  <a class="btn btn-sm btn-primary" target="_blank" rel="noopener" href="{{ external_website }}">
                    Website
                  </a>
                {% endif %}
              </div>
            </div>
          </div>
        </div>
      {% endfor %}
    </div>
  {% endif %}

{% endif %}

{# Web Template: Company Dashboard #}
{% if frappe.session.user == "Guest" %}
  <div class="alert alert-danger">
    You must be logged in to view this page. <a href="/login">Login</a>
  </div>
{% else %}
{% set company_name = frappe.form_dict.get('company') %}
{% if not company_name %}
  <div class="alert alert-warning">No company specified. Append ?company=&lt;Company Name&gt; in URL.</div>
{% endif %}

{% set company = company_name and frappe.get_doc("Company", company_name) %}
{% set projects = company and frappe.get_all(
  "Project",
  filters={"company": company.name},
  fields=["name","project_name","status","start_date","end_date"]
) or [] %}

{% if company %}
  <div class="d-flex justify-content-between align-items-center mb-3">
    <div>
      <h2 class="mb-1">{{ company.company_name }}</h2>
      <div class="text-muted">
        <strong>Code:</strong> {{ company.name }}
        {% if company.email %} | <strong>Email:</strong> {{ company.email }}{% endif %}
        {% if company.phone %} | <strong>Phone:</strong> {{ company.phone }}{% endif %}
      </div>
    </div>

    <div class="d-flex gap-2">
      {% if frappe.session.user != "Guest" %}
        {# QUICK-FIX LINKS (no prefill) #}


            <a class="btn btn-primary" href="/new-project/new?company={{ company.name }}">New Project</a>

            <a class="btn btn-warning" href="/company-form/{{ company.name }}">Edit Company</a>


        {# If you enable URL prefill on Project Web Form (field 'company'), you may use: #}
        {# <a class="btn btn-primary" href="/project-form?company={{ company.name }}">New Project</a> #}
      {% endif %}
      <a class="btn btn-outline-secondary" href="/company-members?company={{ company.name }}">Employees</a>
    </div>
  </div>

  <h4 class="mb-2">Projects</h4>

  <!-- 🔍 Search box -->
  <input type="text" id="projectSearch" class="form-control mb-2"
         placeholder="Search projects by name, code, status...">

  <table class="table" id="projectsTable">
    <thead>
      <tr><th>Name</th><th>Code</th><th>Status</th><th>Start</th><th>End</th></tr>
    </thead>
    <tbody>
      {% for p in projects %}
      <tr>
        <td><a href="/project-dashboard?project={{ p.name }}">{{ p.project_name }}</a></td>
        <td>{{ p.name }}</td>
        <td>{{ p.status or "" }}</td>
        <td>{{ p.start_date or "" }}</td>
        <td>{{ p.end_date or "" }}</td>
      </tr>
      {% endfor %}
      {% if not projects %}
      <tr><td colspan="5" class="text-muted">No projects yet.</td></tr>
      {% endif %}
    </tbody>
  </table>

  <script>
    const inp = document.getElementById("projectSearch");
    if (inp) {
      inp.addEventListener("keyup", function () {
        const filter = this.value.toLowerCase();
        document.querySelectorAll("#projectsTable tbody tr").forEach(function (row) {
          row.style.display = row.innerText.toLowerCase().includes(filter) ? "" : "none";
        });
      });
    }
  </script>
{% endif %}
{% endif %}

{% if frappe.session.user == "Guest" %}
  <div class="alert alert-danger">
    You must be logged in to view this page. <a href="/login">Login</a>
  </div>
{% else %}

{% set project_name = frappe.form_dict.get('project') %}
{% if not project_name %}
  <div class="alert alert-warning">No project specified. Append ?project=&lt;Project Name&gt; in URL.</div>
{% endif %}

{% set project = project_name and frappe.get_doc("Project", project_name) %}
{% set tasks = project and frappe.get_all(
  "Task",
  filters={"project": project.name},
  fields=["name", "task_name", "assignee", "status", "priority", "due_date"]
) or [] %}

{% if project %}
  <div class="d-flex justify-content-between align-items-center mb-3">
    <div>
      <h2 class="mb-1">{{ project.project_name }}</h2>
      <div class="text-muted">
        <strong>Code:</strong> {{ project.name }} |
        <strong>Status:</strong> {{ project.status or "" }}
      </div>
    </div>

    <div class="d-flex gap-2">

            <a class="btn btn-success" href="/new-task/new?project={{ project.name }}">New Task</a>

            <a class="btn btn-warning" href="/project-form/{{ project.name }}">Edit Project</a>



      <a class="btn btn-outline-secondary" href="/company-dashboard?company={{ project.company }}">Back to Company</a>
    </div>
  </div>

  <h4 class="mb-2">Tasks</h4>
  <input type="text" id="taskSearch" class="form-control mb-2"
         placeholder="Search tasks by subject, assignee, status...">

  <table class="table" id="tasksTable">
    <thead>
      <tr><th>Task</th><th>Assignee</th><th>Status</th><th>Priority</th><th>Due</th></tr>
    </thead>
    <tbody>
      {% for t in tasks %}
      <tr>
        <td><a href="/task-form/{{ t.name }}">{{ t.task_name or t.name }}</a></td>
        
        <td>{{ t.assignee or "" }}</td>
        <td>{{ t.status or "" }}</td>
        <td>{{ t.priority or "" }}</td>
        <td>{{ t.due_date or "" }}</td>
      </tr>
      {% endfor %}
      {% if not tasks %}
      <tr><td colspan="5" class="text-muted">No tasks yet.</td></tr>
      {% endif %}
    </tbody>
  </table>

  <script>
    const ts = document.getElementById("taskSearch");
    if (ts) {
      ts.addEventListener("keyup", function () {
        const filter = this.value.toLowerCase();
        document.querySelectorAll("#tasksTable tbody tr").forEach(function (row) {
          row.style.display = row.innerText.toLowerCase().includes(filter) ? "" : "none";
        });
      });
    }
  </script>
{% endif %}
{% endif %}

{# Web Template: Company Members (Employee-based, v15-safe) #}
{% if frappe.session.user == "Guest" %}
  <div class="alert alert-danger">
    You must be logged in to view this page. <a href="/login">Login</a>
  </div>
{% else %}

  {% set company_name = frappe.form_dict.get('company') %}
  {% if not company_name %}
    <div class="alert alert-warning">No company specified. Append ?company=&lt;Company Name&gt; in URL.</div>
  {% endif %}

  {% set company = company_name and frappe.get_doc("Company", company_name) %}

  {% if company %}
    <div class="d-flex justify-content-between align-items-center mb-3">
      <h2 class="mb-0">Employees / Members — {{ company.company_name }}</h2>
      <div class="d-flex gap-2">
        {# Create-only: force blank form; prefill company if enabled #}

            <a class="btn btn-primary" href="/new-employee/new?company={{ company.name }}">Add Employee</a>


        <a class="btn btn-outline-secondary" href="/company-dashboard?company={{ company.name }}">Back to Company</a>
      </div>
    </div>

    {% set employees = frappe.get_all(
      "Employee",
      filters={"company": company.name},
      fields=["name","employee_name","email","phone","designation","status"]
    ) %}

    {% if employees %}
      <table class="table">
        <thead>
          <tr>
            <th>Name</th><th>Designation</th><th>Status</th><th>Email</th><th>Phone</th><th></th>
          </tr>
        </thead>
        <tbody>
          {% for e in employees %}
          <tr>
            <td>{{ e.employee_name }}</td>
            <td>{{ e.designation or "" }}</td>
            <td>{{ e.status or "" }}</td>
            <td>{{ e.email or "" }}</td>
            <td>{{ e.phone or "" }}</td>
            <td>
              <a class="btn btn-sm btn-warning" href="/employee-form/{{ e.name }}">Edit</a>
            </td>
          </tr>
          {% endfor %}
        </tbody>
      </table>
    {% else %}
      <div class="text-muted">No employees found.</div>
    {% endif %}
  {% endif %}

{% endif %}
